{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "id": "day1",
        "title": "Day 1: Arashiyama Nature",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto_Japan.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "morning": "Morning: Walk through the Bamboo Grove and visit Tenryu-ji Zen Garden.",
        "afternoon": "Afternoon: Interactive child-friendly tea ceremony at a local studio.",
        "evening": "Evening: Dinner at a conveyor belt sushi restaurant near Kyoto Station.",
        "costActivities": "Activities $90",
        "costMeals": "Meals $150",
        "actionLabel": "Arashiyama Guide",
        "actionUrl": "https://www.japan-guide.com/e/e3912.html"
      },
      {
        "id": "day2",
        "title": "Day 2: Nara Deer Excursion",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Deer_in_Nara_Park_2.jpg/1200px-Deer_in_Nara_Park_2.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "morning": "Morning: Half-day trip to Nara Park to feed the friendly wild deer.",
        "afternoon": "Afternoon: Visit Todai-ji Temple to see the Great Buddha statue.",
        "evening": "Evening: Relaxed family dinner in the Gion district.",
        "costActivities": "Activities $60",
        "costMeals": "Meals $140",
        "actionLabel": "Nara Park Info",
        "actionUrl": "https://www.visitnara.jp/venues/A0001/"
      },
      {
        "id": "day3",
        "title": "Day 3: Kyoto Culture & History",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Kinkaku-ji_in_Kyoto.jpg/1200px-Kinkaku-ji_in_Kyoto.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "morning": "Morning: Visit Kinkaku-ji (Golden Pavilion) and Ryoan-ji Zen Garden.",
        "afternoon": "Afternoon: Explore Nishiki Market for local snacks and souvenirs.",
        "evening": "Evening: Farewell dinner at a traditional Izakaya.",
        "costActivities": "Activities $100",
        "costMeals": "Meals $160",
        "actionLabel": "Kyoto Culture Guide",
        "actionUrl": "https://www.japan-guide.com/e/e2158.html"
      }
    ],
    "budget": [
      {
        "Category": "Meals",
        "Day 1": "$150",
        "Day 2": "$140",
        "Day 3": "$160",
        "Total": "$450"
      },
      {
        "Category": "Activities",
        "Day 1": "$90",
        "Day 2": "$60",
        "Day 3": "$100",
        "Total": "$250"
      },
      {
        "Category": "Transport",
        "Day 1": "$40",
        "Day 2": "$60",
        "Day 3": "$40",
        "Total": "$140"
      },
      {
        "Category": "Accommodation",
        "Day 1": "$300",
        "Day 2": "$300",
        "Day 3": "$300",
        "Total": "$900"
      },
      {
        "Category": "Total",
        "Day 1": "$580",
        "Day 2": "$560",
        "Day 3": "$600",
        "Total": "$1,740"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "subtitle_h2",
        "itinerary_list",
        "budget_title",
        "budget_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Spring Family Fun in Kyoto",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_h2": {
      "type": "Text",
      "props": {
        "text": "3-Day Nature & Heritage Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "repeat": {
        "statePath": "/itinerary",
        "key": "id"
      },
      "children": [
        "day_card"
      ]
    },
    "day_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day_header_stack",
        "day_image",
        "day_morning",
        "day_afternoon",
        "day_evening",
        "day_cost_label",
        "day_cost_activities",
        "day_cost_meals",
        "day_action_button"
      ]
    },
    "day_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day_title",
        "day_icon"
      ]
    },
    "day_title": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "title"
        },
        "variant": "h3"
      },
      "children": []
    },
    "day_icon": {
      "type": "Icon",
      "props": {
        "name": {
          "$item": "icon"
        }
      },
      "children": []
    },
    "day_image": {
      "type": "Image",
      "props": {
        "url": {
          "$item": "image"
        },
        "fit": "cover"
      },
      "children": []
    },
    "day_morning": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "morning"
        }
      },
      "children": []
    },
    "day_afternoon": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "afternoon"
        }
      },
      "children": []
    },
    "day_evening": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "evening"
        }
      },
      "children": []
    },
    "day_cost_label": {
      "type": "Text",
      "props": {
        "text": "Cost:",
        "variant": "label"
      },
      "children": []
    },
    "day_cost_activities": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "costActivities"
        }
      },
      "children": []
    },
    "day_cost_meals": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "costMeals"
        }
      },
      "children": []
    },
    "day_action_button": {
      "type": "Button",
      "props": {
        "label": {
          "$item": "actionLabel"
        }
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": {
              "$item": "actionUrl"
            }
          }
        }
      },
      "children": []
    },
    "budget_title": {
      "type": "Text",
      "props": {
        "text": "Estimated Daily Budget (USD - Family of 4)",
        "variant": "h2"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "statePath": "/budget",
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Day 1",
            "label": "Day 1"
          },
          {
            "key": "Day 2",
            "label": "Day 2"
          },
          {
            "key": "Day 3",
            "label": "Day 3"
          },
          {
            "key": "Total",
            "label": "Total"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table",
        "numericColumns": [
          "Day 1",
          "Day 2",
          "Day 3",
          "Total"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "kyoto_bus_button",
        "nara_access_button"
      ]
    },
    "kyoto_bus_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Bus Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.city.kyoto.lg.jp/kotsu/cmsfiles/contents/0000019/19770/03AR(EN)202303.pdf"
          }
        }
      },
      "children": []
    },
    "nara_access_button": {
      "type": "Button",
      "props": {
        "label": "Nara Access Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e4107.html"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "japan_guide_button",
        "visit_kyoto_button"
      ]
    },
    "japan_guide_button": {
      "type": "Button",
      "props": {
        "label": "Japan Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/"
          }
        }
      },
      "children": []
    },
    "visit_kyoto_button": {
      "type": "Button",
      "props": {
        "label": "Visit Kyoto Official"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://kyoto.travel/en/"
          }
        }
      },
      "children": []
    }
  }
}
